    "sql": "CREATE OR REPLACE FUNCTION public.claim_asset_v2( p_claim_id UUID ) RETURNS JSONB AS $$ DECLARE v_caller_id UUID; v_claim RECORD; v_save JSONB; v_new_save JSONB; v_item_name TEXT; v_qty INT; v_curr_qty INT; BEGIN v_caller_id := auth.uid(); SELECT * INTO v_claim FROM claim_queue WHERE id = p_claim_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Reclamo no encontrado.'; END IF; IF v_claim.user_id != v_caller_id THEN RAISE EXCEPTION 'No autorizado.'; END IF; SELECT save_data INTO v_save FROM game_saves WHERE user_id = v_caller_id FOR UPDATE; v_new_save := v_save; CASE v_claim.asset_data->>'type' WHEN 'pokemon' THEN v_new_save := jsonb_set(v_new_save, '{team}', (v_new_save->'team') || jsonb_build_array(v_claim.asset_data->'data')); WHEN 'money' THEN v_new_save := jsonb_set(v_new_save, '{money}', to_jsonb((v_new_save->>'money')::BIGINT + (v_claim.asset_data->'data')::BIGINT)); WHEN 'item' THEN v_item_name := v_claim.asset_data->'data'->>'name'; v_qty := COALESCE((v_claim.asset_data->'data'->>'qty')::INT, 1); IF NOT (v_new_save ? 'inventory') OR v_new_save->'inventory' IS NULL THEN v_new_save := jsonb_set(v_new_save, '{inventory}', '{}'::jsonb); END IF; v_curr_qty := COALESCE((v_new_save->'inventory'->>v_item_name)::INT, 0); v_new_save := jsonb_set( v_new_save, ARRAY['inventory', v_item_name], to_jsonb(v_curr_qty + v_qty) ); END CASE; UPDATE game_saves SET save_data = v_new_save, last_save_id = gen_random_uuid(), updated_at = NOW() WHERE user_id = v_caller_id; DELETE FROM claim_queue WHERE id = p_claim_id; RETURN v_new_save; END; $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog; REVOKE EXECUTE ON FUNCTION public.claim_asset_v2(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.claim_asset_v2(uuid) TO authenticated, service_role; INSERT INTO public.system_config (key, value) VALUES ('db_version', '20260519235000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();",
